// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;

    function setUp() public { c = new demo(); }

    // fuzzed params: from (address), v (amount), nTos (how many recipients)
    // We pass the adversarial callee (Reverter) to c as caddress so its call will fail.
    function testFuzz_property(address from, uint256 v, uint8 nTos) public {
        // keep number of tos reasonable but allow 1..10
        uint8 tosCount = uint8(bound(nTos, 1, 10));
        // build tos array
        address[] memory tos = new address[](tosCount);
        for (uint i = 0; i < tosCount; i++) {
            // use distinct addresses derived from the fuzzed `from` to vary inputs
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, i)))));
        }

        // deploy a callee that always reverts so the low-level call returns (false, ...)
        Reverter reverter = new Reverter();

        // call c.transfer and observe whether it reverts via try/catch
        bool ok;
        try c.transfer(from, address(reverter), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL FACT (reference satisfies for ALL inputs): when the callee reverts, C.transfer MUST revert
        // i.e., ok must be false. The mutant removed the revert on failed call, so for some inputs ok==true.
        assertTrue(!ok);
    }
}

// Adversarial helper: forces calls to fail by reverting in the called function selector
contract Reverter {
    // match the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address, address, uint256) external pure {
        revert("revert from callee");
    }

    // fallback just reverts to cover malformed selectors
    fallback() external payable {
        revert("fallback revert");
    }
}
